import{_ as i,a0 as a,w as p,s as u,ao as r,I as s,x as l,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"我最喜歡在 Linux 上玩的休閒遊戲 | LCTT x X-CMD","titleTemplate":false,"description":"我最喜歡在 Linux 上玩的休閒遊戲 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我最喜歡在 Linux 上玩的休閒遊戲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我最喜歡在 Linux 上玩的休閒遊戲 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220226 My favorite casual games to play on Linux","title":"我最喜歡在 Linux 上玩的休閒遊戲","tag":"202204","desc":""},"relativePath":"202204/20220226 My favorite casual games to play on Linux.md","filePath":"[post].md"}'),f={name:"202204/20220226 My favorite casual games to play on Linux.md"};function d(m,t,g,k,x,K){const o=a("Link");return p(),u("div",null,[t[24]||(t[24]=r('<h1 id="我最喜歡在-linux-上玩的休閒遊戲" tabindex="-1">我最喜歡在 Linux 上玩的休閒遊戲 <a class="header-anchor" href="#我最喜歡在-linux-上玩的休閒遊戲" aria-label="Permalink to “我最喜歡在 Linux 上玩的休閒遊戲”">​</a></h1><blockquote><p>在編譯開源代碼的同時在 Linux 上玩電子遊戲。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202204/05/162045ecqsvd80cq2050dd.jpg" alt=""></p><p>我喜歡一款可以讓自己沉浸數小時的好遊戲，但我並不總是能夠忽略工作而消失在電子遊戲中。儘管如此，我還是喜歡不時的接受有趣的挑戰，當我的計算機忙於做一些我需要等待的事情時，我最喜歡啓動的兩個應用程序是來自 KDE 遊戲包的遊戲：<strong>KBlocks</strong> 和 <strong>Kolf</strong>。</p><h3 id="kblocks" tabindex="-1">KBlocks <a class="header-anchor" href="#kblocks" aria-label="Permalink to “KBlocks”">​</a></h3><p>我最喜歡的電子遊戲是這種從方塊從天上掉下來，最好是落成一排，當方塊相鄰時就會神奇的消失的遊戲。KBlocks 就是這樣的，它的實現很棒。它可以使用<strong>左箭頭</strong>和<strong>右箭頭</strong>控制方塊進行旋轉，使用<strong>下箭頭</strong>讓方塊更快的下落，使用<strong>空格鍵</strong>直接落下方塊，不同的難度級別，方塊下落的速度不同。</p><p><img src="https://opensource.com/sites/default/files/kblocks.jpg" alt="KBlocks" title="KBlocks"></p>',7)),s("p",null,[t[1]||(t[1]=l("（Seth Kenlon, ",-1)),e(o,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:n(()=>[...t[0]||(t[0]=[l("CC BY-SA 4.0",-1)])]),_:1}),t[2]||(t[2]=l("）",-1))]),t[25]||(t[25]=r('<p>KBlocks 的默認主題是古埃及，這對遊戲的玩法沒有影響，但對於古埃及的愛好者來説可能是愉快的遊戲體驗。不過，你可以在“<ruby>配置 KBlocks<rt>Configure KBlocks</rt></ruby>”菜單項中更改主題。有一個名為 “Plasma” 的替代主題，或者你可以單擊“<ruby>獲取新主題<rt>Get New Themes</rt></ruby>”按鈕並下載由用户貢獻的主題。</p><p><img src="https://opensource.com/sites/default/files/kblocks-invaders.jpg" alt="KBlocks Invaders by José Jorge" title="KBlocks Invaders by José Jorge"></p><p>(Seth Kenlon, CC BY-SA 4.0)</p><p>主題純粹是美學方面的事情，但就藝術類型的人而言，為休閒遊戲創建主題可能是為開源項目作出貢獻的一種有趣方式。</p><h4 id="引導我進入-kde-plasma-桌面的遊戲" tabindex="-1">引導我進入 KDE Plasma 桌面的遊戲 <a class="header-anchor" href="#引導我進入-kde-plasma-桌面的遊戲" aria-label="Permalink to “引導我進入 KDE Plasma 桌面的遊戲”">​</a></h4><p>我承認，KBlocks 對我來説很難放下。事實上，正是我在會議期間玩遊戲的願望讓我在 Emacs 中找到了 <code>M-x tetris</code> 命令，這反過來又讓我發現並愛上了 Linux。這個遊戲有很大的魅力。也許 KBlocks 將成為你發現 KDE Plasma 桌面的途徑？</p><h3 id="kolf" tabindex="-1">Kolf <a class="header-anchor" href="#kolf" aria-label="Permalink to “Kolf”">​</a></h3><p>我不喜歡現實生活中的高爾夫，但在電腦上，迷你高爾夫結合了模擬物理和有趣的關卡設計，既令人愉快，又令人沮喪。Kolf 的目標如你所料：將高爾夫球打入洞中。當然，目的地總是在拐角處、需要越過山丘、經過池塘或者在牆後，因此你的目標是計算球速、摩擦力、坡度和軌跡，使其完美地讓球回到球洞並儘可能少的擊打球。</p><p><img src="https://opensource.com/sites/default/files/kolf.jpg" alt="Miniature golf" title="Miniature golf"></p>',9)),s("p",null,[t[4]||(t[4]=l("（Seth Kenlon, ",-1)),e(o,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:n(()=>[...t[3]||(t[3]=[l("CC BY-SA 4.0",-1)])]),_:1}),t[5]||(t[5]=l("）",-1))]),t[26]||(t[26]=s("p",null,"它從來沒有看起來那麼簡單，而且我認為看着高爾夫球從物體上反彈，並滾下你從未打算讓它靠近的山丘，這永遠不會過時。",-1)),t[27]||(t[27]=s("h4",{id:"設計自己的球場",tabindex:"-1"},[l("設計自己的球場 "),s("a",{class:"header-anchor",href:"#設計自己的球場","aria-label":"Permalink to “設計自己的球場”"},"​")],-1)),t[28]||(t[28]=s("p",null,"當你嘗試設計自己的迷你高爾夫球場時，樂趣才真正開始。是的，Kolf 有一個關卡編輯器，你可以在其中建造牆壁、放置池塘、山丘和沙坑，添加彈球式保險槓等等。",-1)),t[29]||(t[29]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/kolf-edit.jpg",alt:"Kolf editor",title:"Kolf editor"})],-1)),s("p",null,[t[7]||(t[7]=l("（Seth Kenlon, ",-1)),e(o,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:n(()=>[...t[6]||(t[6]=[l("CC BY-SA 4.0",-1)])]),_:1}),t[8]||(t[8]=l("）",-1))]),t[30]||(t[30]=s("p",null,"因為 Kolf 可以是多人遊戲，所以給每個玩家五分鐘的時間來設計一個關卡，然後看看誰在誰的關卡上做的最好，這特別有趣。",-1)),t[31]||(t[31]=s("h3",{id:"linux-kde-遊戲",tabindex:"-1"},[l("Linux KDE 遊戲 "),s("a",{class:"header-anchor",href:"#linux-kde-遊戲","aria-label":"Permalink to “Linux KDE 遊戲”"},"​")],-1)),t[32]||(t[32]=s("p",null,"這絕不是 KDE 項目中僅有的兩款遊戲。還有許多其它遊戲，包括卡牌遊戲、拼圖遊戲和街機遊戲。KDE 遊戲包的好處是，它們包含了你可以隨時走開的遊戲，而且它們只需要你一點點的注意力。我在編譯代碼時使用這些遊戲來消磨時間。有時候我並不能完整的玩完一局遊戲，但我總是很欣賞這種心理狀態的微妙轉變。",-1)),t[33]||(t[33]=s("hr",null,null,-1)),s("p",null,[t[10]||(t[10]=l("via: ",-1)),e(o,{href:"https://opensource.com/article/22/2/casual-gaming-linux-kde"},{default:n(()=>[...t[9]||(t[9]=[l("https://opensource.com/article/22/2/casual-gaming-linux-kde",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=l("作者：",-1)),e(o,{href:"https://opensource.com/users/seth"},{default:n(()=>[...t[11]||(t[11]=[l("Seth Kenlon",-1)])]),_:1}),t[16]||(t[16]=l(" 選題：",-1)),e(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[12]||(t[12]=[l("lujun9972",-1)])]),_:1}),t[17]||(t[17]=l(" 譯者：",-1)),e(o,{href:"https://github.com/perfiffer"},{default:n(()=>[...t[13]||(t[13]=[l("perfiffer",-1)])]),_:1}),t[18]||(t[18]=l(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[14]||(t[14]=[l("wxy",-1)])]),_:1})]),s("p",null,[t[21]||(t[21]=l("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[19]||(t[19]=[l("LCTT",-1)])]),_:1}),t[22]||(t[22]=l(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:n(()=>[...t[20]||(t[20]=[l("Linux中國",-1)])]),_:1}),t[23]||(t[23]=l(" 榮譽推出",-1))])])}const L=i(f,[["render",d]]);export{C as __pageData,L as default};
